# Source of truth for the genre bank -> generates Source/GenreBank.h
# Lanes: K S C R H O P Sh T Cr   ('.' rest, 1 ghost, 2 normal, 3 accent,
#   x = normal + 2-hit ratchet, y = ghost + 2-hit ratchet, z = normal + 3-hit ratchet, L/M/H/F = tom low/mid/high/floor)
# Each genre: tempo, swing %, ghosts, loosen, dust, push ms per lane (10), fill weights (toms, roll, kicks, hats, drop), fill len (4/8/16), 4 variations.
E = '................'
G = []
def g(name, cat, tempo, swing, ghosts, loosen, dust, push, fills, flen, *vars):
    for v in vars:
        assert len(v) == 10, (name, len(v))
        for r in v: assert len(r) == 16, (name, r)
    assert len(push) == 10
    G.append(dict(name=name, cat=cat, tempo=tempo, swing=swing, ghosts=ghosts, loosen=loosen, dust=dust, push=push, fills=fills, flen=flen, vars=vars))

