# ---------------------------------------------------------------- emit C++
def cell(c):
    m = {'1':(40,1,1),'2':(96,1,1),'3':(127,1,1),'x':(96,2,1),'y':(40,2,1),'z':(96,3,1),'L':(100,1,1),'M':(100,1,2),'H':(100,1,3),'F':(100,1,0)}
    return m.get(c)
out = ['#pragma once', '// GENERATED by tools/genres.py - edit that file, not this one.', '#include "DrumVoices.h"', '',
       'namespace genres', '{', '    struct Genre', '    {', '        const char* name; const char* cat;', '        float tempo, swing, ghosts, loosen, dust;',
       '        float push[10]; float fill[5]; int fillLen;', '        const char* v[4][10];', '    };', '',
       '    inline const Genre* all()', '    {', '        static const Genre g[] = {']
for x in G:
    vs = ', '.join('{ ' + ', '.join('"%s"' % r for r in v) + ' }' for v in x['vars'])
    out.append('            { "%s", "%s", %.1ff, %.1ff, %.2ff, %.2ff, %.2ff, { %s }, { %s }, %d, { %s } },' % (
        x['name'], x['cat'], x['tempo'], x['swing'], x['ghosts'], x['loosen'], x['dust'],
        ', '.join('%.1ff' % p for p in x['push']), ', '.join('%.2ff' % f for f in x['fills']), x['flen'], vs))
out += ['        };', '        return g;', '    }', '    constexpr int count = %d;' % len(G), '}', '']
open('/home/claude/shufflebuddy/Source/GenreBank.h', 'w').write('\n'.join(out))
print(len(G), 'genres written')
